import {DEMO_TRACK,validAudioTracks} from './expansion-dfplayer.js';
let enabled=false,lastProject,lastStates,lastRunning;const players=new Map();
export function dfplayerInspector(c){if(c.type!=='dfplayer')return '';return `<p class="support-note">${c.params.audioTracks?.length||1} ses dosyası · dosyalar yalnız bu projede tutulur. MP3/WAV, dosya başına 1 MiB, toplam 2 MiB.</p><label>Ses dosyalarını seç <input id="dfplayer-files" type="file" accept="audio/mpeg,audio/mp3,audio/wav,audio/x-wav" multiple></label><button id="dfplayer-audio-enable" type="button">Ses çıkışını etkinleştir</button><p id="dfplayer-audio-status" role="status"></p>`;}
export function bindDFPlayer(c,edit,toast){if(c.type!=='dfplayer')return;document.getElementById('dfplayer-audio-enable').onclick=()=>{enabled=true;for(const p of players.values()){const volume=p.audio.volume;p.audio.volume=0;p.audio.play().then(()=>{p.audio.pause();p.audio.currentTime=0;p.audio.volume=volume;updateDFPlayerAudio(lastProject,lastStates,lastRunning);}).catch(error=>{p.audio.volume=volume;p.audio.dataset.playbackError=error.name;});}updateDFPlayerAudio(lastProject,lastStates,lastRunning);};document.getElementById('dfplayer-files').onchange=async e=>{const files=[...e.target.files];try{if(!files.length)return;if(files.length>8||files.some(f=>f.size>1048576)||files.reduce((n,f)=>n+f.size,0)>2097152)throw Error('En fazla 8 dosya; dosya başına 1 MiB, toplam 2 MiB.');const tracks=[];for(const [i,file]of files.entries()){const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const duration=await new Promise((resolve,reject)=>{const a=new Audio(data),timer=setTimeout(()=>{a.src='';reject(Error('Ses dosyası çözümlenemedi.'));},5000);a.onloadedmetadata=()=>{clearTimeout(timer);const d=a.duration;a.src='';resolve(d);};a.onerror=()=>{clearTimeout(timer);reject(Error('Tarayıcı bu ses biçimini çözemedi.'));};});tracks.push({index:i+1,folder:1,file:i+1,name:file.name.slice(0,100),duration,data});}if(!validAudioTracks(tracks))throw Error('Geçersiz ses dosyası/biçimi.');edit(()=>c.params.audioTracks=tracks);toast('Ses dosyaları projeye eklendi. UART komutlarıyla oynatabilirsiniz.');}catch(error){toast(error.message);}};}
export function updateDFPlayerAudio(project,states={},running=false){lastProject=project;lastStates=states;lastRunning=running;const ids=new Set();for(const c of project?.components||[]){if(c.type!=='dfplayer')continue;ids.add(c.id);const d=states[c.id],track=(c.params.audioTracks?.length?c.params.audioTracks:[DEMO_TRACK]).find(t=>t.index===d?.track),key=track?.data;if(!players.has(c.id)){const audio=new Audio();audio.hidden=true;audio.dataset.dfplayerAudio=c.id;document.body.append(audio);players.set(c.id,{audio,key:null,generation:null});}const p=players.get(c.id);if(p.key!==key){p.audio.pause();p.audio.src=key||'';p.key=key;p.generation=null;}const shouldPlay=enabled&&running&&d?.powered&&d?.playing&&track;p.audio.dataset.firmwarePlaying=String(!!d?.playing);p.audio.dataset.running=String(!!running);p.audio.dataset.enabled=String(enabled);p.audio.volume=(d?.volume??20)/30;if(shouldPlay){if(p.generation!==d.generation||Math.abs(p.audio.currentTime-(d.position??0))>.35){try{p.audio.currentTime=d.position??0;}catch{}p.generation=d.generation;}if(p.audio.paused&&!p.pending){p.pending=true;p.audio.play().then(()=>{delete p.audio.dataset.playbackError;}).catch(error=>{if(error.name!=='AbortError')p.audio.dataset.playbackError=error.name;}).finally(()=>p.pending=false);}}else p.audio.pause();}for(const[id,p]of players)if(!ids.has(id)){p.audio.pause();p.audio.src='';p.audio.remove();players.delete(id);}const label=document.getElementById('dfplayer-audio-status');if(label)label.textContent=enabled?'Ses açık · UART play/pause/volume kontrollü':'Ses kapalı · etkinleştirme düğmesine basın';}
